    const val = preorder[pre++];             // preorder gives the root
    const mid = pos.get(val);                // root splits inorder in two
    const node = new TreeNode(val);
    node.left = build(lo, mid - 1);          // left part first (preorder!)
    node.right = build(mid + 1, hi);
